  "onlyFriendsApp": [
    {
      "from": "Fan Name",
      "to": "post creator name",
      "message": "message text",
      "postId": "the post id from the request",
      "tip": 5
    },
    {
      "from": "Another Fan",
      "to": "post creator name",
      "message": "message text",
      "postId": "the post id from the request"
    }
  ]
}
postId is optional: include the exact request post id when a DM is about this post, or omit it for a general message. tip is optional, OnlyFriends-only, and must be a positive number; it credits the creator's OnlyFriends wallet.

